const cfg = $('Config').first().json;
const since = Date.now() - cfg.daysBack * 86400000;
const rows = $input.all().map(i => i.json).filter(r => {
  const t = Date.parse(r.askedAt);
  const isTest = String(r.question || '').startsWith('[TEST]');
  return t >= since && (cfg.includeTestRows || !isTest);
});
const norm = q => String(q).replace(/^\[TEST\]\s*/, '').trim().toLowerCase().replace(/[?!.]+$/, '');
const count = (arr) => { const m = {}; arr.forEach(x => { if (x) m[x] = (m[x] || 0) + 1; }); return Object.entries(m).sort((a, b) => b[1] - a[1]); };
const answered = rows.filter(r => r.answered);
const unanswered = rows.filter(r => !r.answered);
const unansweredList = Array.from(new Set(unanswered.map(r => String(r.question).replace(/^\[TEST\]\s*/, '').trim()))).slice(0, 25);
const fb = $('Get Feedback').all().map(i => i.json).filter(r => r.rating && Date.parse(r.askedAt) >= since && (cfg.includeTestRows || !String(r.question || '').startsWith('TEST')));
const fbDownRows = fb.filter(r => r.rating === 'down');
const stats = {
  total: rows.length,
  users: new Set(rows.map(r => r.userHash)).size,
  answered: answered.length,
  unanswered: unanswered.length,
  answeredPct: rows.length ? Math.round(answered.length * 100 / rows.length) : 0,
  topQuestions: count(rows.map(r => norm(r.question))).slice(0, 5),
  topSources: count(answered.map(r => String(r.topSource || '').replace(/\.pdf$/i, ''))).slice(0, 5),
  unansweredList,
  days: cfg.daysBack,
  fbUp: fb.filter(r => r.rating === 'up').length,
  fbDown: fbDownRows.length,
  fbDownList: fbDownRows.slice(0, 10).map(r => ({ q: String(r.question || '').slice(0, 120), src: String(r.topSource || '').replace(/\.pdf$/i, '') }))
};
const prompt = unansweredList.length
  ? 'Ти аналітик бази знань компанії. Нижче запитання співробітників, на які бот не знайшов відповіді у внутрішніх документах. Згрупуй їх за темами і для кожної теми коротко запропонуй, який документ або розділ варто додати. Відповідай українською, маркованим списком, не більше 5 пунктів, без вступу.\n\nЗапитання:\n- ' + unansweredList.join('\n- ')
  : '';
return [{ json: { stats, prompt, hasUnanswered: unansweredList.length > 0, space: cfg.reportSpace } }];

const base = $('Build Stats').first().json;
const s = base.stats;
let gaps = '';
try {
  const g = $('Summarize Gaps (Gemini)').first().json;
  gaps = (((g.candidates || [])[0] || {}).content || {}).parts ? g.candidates[0].content.parts.map(p => p.text || '').join('') : '';
} catch (e) { gaps = ''; }
const esc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const md = t => esc(t).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/^\s*[*-]\s+/gm, '• ').replace(/\n/g, '<br>');
const widgets = [];
if (!s.total) {
  widgets.push({ textParagraph: { text: 'За останні ' + s.days + ' дн. запитань до бота не було.' } });
} else {
  widgets.push({ textParagraph: { text: '<b>Запитань:</b> ' + s.total + ' від ' + s.users + ' користувачів<br><b>З відповіддю в базі:</b> ' + s.answered + ' (' + s.answeredPct + '%)<br><b>Без відповіді:</b> ' + s.unanswered } });
  if (s.topQuestions.length) widgets.push({ divider: {} }, { textParagraph: { text: '<b>Найчастіше питають:</b><br>' + s.topQuestions.map(q => '• ' + esc(q[0]) + ' (' + q[1] + ')').join('<br>') } });
  if (s.topSources.length) widgets.push({ divider: {} }, { textParagraph: { text: '<b>Найпопулярніші документи:</b><br>' + s.topSources.map(q => '• ' + esc(q[0]) + ' (' + q[1] + ')').join('<br>') } });
  if (s.fbUp + s.fbDown) widgets.push({ divider: {} }, { textParagraph: { text: '<b>Оцінки відповідей:</b> 👍 ' + s.fbUp + ', 👎 ' + s.fbDown + ' (' + Math.round(s.fbUp * 100 / (s.fbUp + s.fbDown)) + '% позитивних)' + (s.fbDownList.length ? '<br><br><b>Погано оцінені:</b><br>' + s.fbDownList.map(f => '• ' + esc(f.q) + (f.src ? ' — ' + esc(f.src) : '')).join('<br>') : '') } });
  if (s.unansweredList.length) {
    widgets.push({ divider: {} }, { textParagraph: { text: '<b>Чого немає в документах:</b><br>' + (gaps ? md(gaps) : s.unansweredList.slice(0, 10).map(q => '• ' + esc(q)).join('<br>')) } });
  }
}
const body = { cardsV2: [{ cardId: 'documindyWeekly', card: { header: { title: 'DocuMindy: тижневий звіт', subtitle: 'Останні ' + s.days + ' дн.' }, sections: [{ widgets }] } }] };
return [{ json: { space: base.space, body } }];
